mapper.select:
SELECT P.PLACE_NO, P.PLACE_NAME, P.PLACE_DESCRIPTION, P.ADDR, P.ADDR_DETAIL, P.PHONE_NUMBER AS PHONE, T.TYPE, TD.TYPE_DETAIL_CONTENT AS TYPE_DETAIL, P.VIEW_COUNT, P.X_AXIS, P.Y_AXIS, AS IMAGE_URL FROM PLACE P JOIN TYPE_DETAIL TD ON P.TYPE_DETAIL_NO = TD.TYPE_DETAIL_NO JOIN TYPE T ON TD.TYPE_NO = T.TYPE_NO WHERE P.DEL_YN = 'N'
AND T.TYPE_NO = #{typeNo}
AND TD.TYPE_DETAIL_NO = #{typeDetailNo}
AND EXISTS ( SELECT 1 FROM PLACE_TAG PT WHERE PT.PLACE_NO = P.PLACE_NO AND PT.TAG_NO = #{tagNo} )
ORDER BY P.PLACE_NO
